Station metadata
Station metadata are examined before analysis to identify missing coordinates, duplicate locations, inconsistent station identifiers and potential differences in reference datum.


Show code
station_coordinates &lt;- da |&gt;
  distinct(source, station_id, st_id, latitude, longitude) |&gt;
  arrange(source, station_id)

missing_coordinates &lt;- station_coordinates |&gt;
  filter(is.na(latitude) | is.na(longitude))

if (nrow(missing_coordinates) &gt; 0) {
  missing_coordinates |&gt;
    knitr::kable()

} else {
  cat("No stations have missing latitude or longitude.")
}


#| No stations have missing latitude or longitude.




Show code
coordinate_check &lt;- da |&gt;
  filter(!is.na(latitude), !is.na(longitude)) |&gt;
  distinct(st_id, latitude, longitude) |&gt;
  count(st_id, name = "n_coordinate_pairs") |&gt;
  filter(n_coordinate_pairs &gt; 1)

if (nrow(coordinate_check) &gt; 0) {
  coordinate_check |&gt;
    knitr::kable()

} else {

  cat("Every station is associated with a single coordinate pair.")
}


#| Every station is associated with a single coordinate pair.




Show code
station_id_check &lt;- da |&gt;
  distinct(station_id, st_id)

duplicate_station_ids &lt;- station_id_check |&gt;
  count(st_id, name = "n_station_names") |&gt;
  filter(n_station_names &gt; 1)

if (nrow(duplicate_station_ids) &gt; 0) {
  station_id_check |&gt;
    semi_join(duplicate_station_ids, by = "st_id") |&gt;
    arrange(st_id, station_id) |&gt;
    knitr::kable()

} else {
  cat("Each st_id corresponds to a single station name.")
}


#| Each st_id corresponds to a single station name.
